'use strict';
const $=s=>document.querySelector(s),cfg=window.TMAILER_CONFIG||{};
const state={base:cfg.apiBase||'',ready:!!cfg.ready,token:'',connected:false,folder:'INBOX',offset:0,total:0,messages:[],current:null,generation:0,sending:false,email:'',replyId:''};
const SETTINGS='tmailer-account-settings',SERVICE='tmailer-service';
let toast;
function stored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}
if(!cfg.desktop){const configured=stored(SERVICE,'');if(configured){state.base=configured;state.ready=true;}}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function notice(message,error=false){clearTimeout(toast);$('#notice span').textContent=message;$('#notice').classList.toggle('error',error);$('#notice').hidden=false;if(!error)toast=setTimeout(()=>$('#notice').hidden=true,6500);}
$('#notice button').onclick=()=>$('#notice').hidden=true;
function open(id){const d=$('#'+id);if(!d.open)d.showModal();}
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$('#'+b.dataset.close).close();
function connectionUI(){const missing=!state.ready;$('#statusMode').textContent=cfg.desktop?'Desktop edition':'Web edition';$('#connectionLabel').textContent=state.connected?state.email:'No account connected';$('#accountText').textContent=state.connected?state.email:'Connect account';$('.avatar').textContent=state.connected?state.email[0].toUpperCase():'＋';$('#connectionDot').classList.toggle('connected',state.connected);$('#disconnectBtn').hidden=!state.connected;$('#serviceBtn').hidden=!!cfg.desktop;$('#accountServiceNote').textContent=missing?'A mail connection service hasn’t been connected to this website yet. Add a trusted Tmailer service in Connection settings, or use the desktop app for direct connections.':'';$('#welcomePrivacy').textContent=cfg.desktop?'Passwords stay in this app’s memory.':'Passwords stay in your mail service session.';$('#serviceBanner').hidden=!missing;if(missing){$('#serviceBanner').replaceChildren(el('span','Web mail service isn’t connected yet. '));const b=el('button','Connection settings');b.onclick=()=>openService();$('#serviceBanner').append(b,el('span',' · The desktop app connects directly.'));}$('#statusText').textContent=state.connected?'Connected · '+state.email:missing?'Mail service not connected':'Ready to connect';}
async function raw(action,data={},auth=true){if(!state.ready)throw Error('Connect a Tmailer service in Connection settings, or use the desktop app.');let response;try{response=await fetch(state.base+'/api/'+action,{method:'POST',headers:{'Content-Type':'application/json',...(auth?{'X-Tmailer-Token':state.token}:{})},body:JSON.stringify(data),credentials:'omit'});}catch{throw Error('The Tmailer service could not be reached. Check its address and allowed website origin.');}let result;try{result=await response.json();}catch{throw Error('The address did not return a Tmailer service response.');}if(!response.ok){if(response.status===401){state.token='';state.connected=false;connectionUI();}throw Error(result.error||'Request failed.');}return result;}
async function api(action,data={}){if(!state.token){const r=await raw('session',{},false);state.token=r.token;}return raw(action,data);}
function openAccount(){connectionUI();open('accountDialog');}
function needAccount(){if(state.connected)return true;openAccount();return false;}
$('#accountBtn').onclick=openAccount;$('#welcomeConnect').onclick=openAccount;$('#listConnect').onclick=openAccount;
function openService(){if(cfg.desktop)return;if($('#accountDialog').open)$('#accountDialog').close();$('#serviceUrl').value=state.base;open('serviceDialog');}
$('#serviceBtn').onclick=openService;
$('#serviceForm').onsubmit=async e=>{e.preventDefault();let url;try{url=new URL($('#serviceUrl').value);if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||url.pathname!=='/')throw Error('Use a trusted HTTPS service origin without a path or credentials.');}catch(err){return notice(err.message||'Enter a valid HTTPS service address.',true);}if(state.connected&&!confirm('Changing service will disconnect your current mailbox. Continue?'))return;const old={base:state.base,ready:state.ready,token:state.token};state.base=url.origin;state.ready=true;state.token='';const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const session=await raw('session',{},false);if(!session.token)throw Error('Service did not provide a session.');state.token=session.token;if(state.connected){try{await fetch(old.base+'/api/disconnect',{method:'POST',headers:{'Content-Type':'application/json','X-Tmailer-Token':old.token},body:'{}',credentials:'omit'});}catch{}}state.connected=false;resetMailbox();save(SERVICE,state.base);$('#serviceDialog').close();connectionUI();notice('Service connected. You can now add your email account.');openAccount();}catch(err){Object.assign(state,old);notice(err.message,true);}finally{button.disabled=false;}};
function shortDate(value){const d=new Date(value);return Number.isNaN(d.valueOf())?value:d.toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function sender(v){return v.replace(/<[^>]*>/g,'').replace(/^"|"$/g,'').trim()||v;}
function renderRows(){const query=$('#search').value.toLowerCase();$('#messageRows').replaceChildren();for(const m of state.messages.filter(m=>(m.from+' '+m.subject).toLowerCase().includes(query))){const b=el('button',undefined,'messageRow'+(state.current?.id===m.id?' selected':''));const top=el('div',undefined,'rowTop');top.append(el('span',sender(m.from),'sender'),el('span',shortDate(m.date),'date'));b.append(top,el('div',m.subject||'(No subject)','subject'));b.onclick=()=>openMessage(m.id);$('#messageRows').append(b);}if(!$('#messageRows').children.length)$('#messageRows').append(el('p',query?'No matching messages on this page.':'This mailbox is empty.','info'));$('#count').textContent=state.total+' messages';$('#pageLabel').textContent=state.total?`${state.offset+1}–${Math.min(state.offset+40,state.total)} of ${state.total}`:'0 messages';$('#prevBtn').disabled=state.offset===0;$('#nextBtn').disabled=state.offset+40>=state.total;}
function emptyReader(){state.current=null;$('#reader').replaceChildren(el('div','Select a message to read it here.','welcome'));}
function resetMailbox(){++state.generation;state.folder='INBOX';state.offset=0;state.total=0;state.messages=[];state.current=null;$('#folderTitle').textContent='Inbox';$('#folders').replaceChildren();const b=el('button',undefined,'folder active');b.append(el('span','▣'),document.createTextNode(' Inbox'));b.onclick=()=>needAccount();$('#folders').append(b);emptyReader();renderRows();}
async function refresh(){if(!needAccount())return;const generation=++state.generation;$('#refreshBtn').disabled=true;$('#statusText').textContent='Fetching messages…';$('#messageRows').replaceChildren(el('p','Fetching messages…','info'));try{const r=await api('messages',{folder:state.folder,offset:state.offset});if(generation!==state.generation)return;state.messages=r.messages;state.total=r.total;renderRows();$('#statusText').textContent='Last refreshed '+new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});}catch(err){if(generation===state.generation){notice(err.message,true);$('#messageRows').replaceChildren(el('p','Could not load messages. Use Refresh to try again.','info'));$('#statusText').textContent='Refresh failed';}}finally{if(generation===state.generation)$('#refreshBtn').disabled=false;}}
async function loadFolders(){const {folders}=await api('folders');$('#folders').replaceChildren();for(const folder of folders){const b=el('button',undefined,'folder'+(folder===state.folder?' active':''));b.append(el('span',folder==='INBOX'?'▣':'□'),document.createTextNode(' '+(folder==='INBOX'?'Inbox':folder)));b.title=folder;b.onclick=()=>{state.folder=folder;state.offset=0;$('#folderTitle').textContent=folder==='INBOX'?'Inbox':folder;for(const row of $('#folders').children)row.classList.toggle('active',row===b);emptyReader();refresh();};$('#folders').append(b);}}
let blobs=[];
function clearBlobs(){for(const url of blobs)URL.revokeObjectURL(url);blobs=[];}
async function openMessage(id){const generation=++state.generation;$('#refreshBtn').disabled=false;$('#reader').replaceChildren(el('p','Loading message…','info'));$('.mailbox').classList.remove('readingHidden');try{const m=await api('message',{folder:state.folder,id});if(generation!==state.generation)return;clearBlobs();state.current=m;renderRows();const reader=$('#reader');reader.replaceChildren(el('h2',m.subject||'(No subject)','messageTitle'));const meta=el('div',undefined,'messageMeta');meta.append(el('div','From: '+m.from),el('div','To: '+m.to),el('div',m.date));const actions=el('div',undefined,'readerActions');const reply=el('button','↩ Reply');reply.onclick=()=>compose('reply');const forward=el('button','Forward →');forward.onclick=()=>compose('forward');actions.append(reply,forward);reader.append(meta,actions,el('pre',m.body||'(This message has no readable text body.)','body'));for(const a of m.attachments){const link=el('a','↓ '+a.name,'attachment');link.href=URL.createObjectURL(new Blob([Uint8Array.from(atob(a.data),c=>c.charCodeAt(0))],{type:'application/octet-stream'}));blobs.push(link.href);link.download=a.name;reader.append(link);}if(innerWidth<720)reader.scrollIntoView({behavior:'smooth'});}catch(err){if(generation===state.generation){notice(err.message,true);$('#reader').replaceChildren(el('p','Could not open this message.','info'));}}}
$('#accountForm').onsubmit=async e=>{e.preventDefault();if(!state.ready){openService();return;}const c=Object.fromEntries(new FormData(e.target));c.remember=e.target.elements.remember.checked;const button=$('#connectBtn');button.disabled=true;button.textContent='Testing server logins…';try{const r=await api('connect',c);state.connected=true;state.email=r.email;state.folder='INBOX';state.offset=0;$('#folderTitle').textContent='Inbox';const safe={};for(const key of ['email','username','protocol','incoming','incoming_security','smtp','smtp_security','smtp_username'])safe[key]=c[key];save(SETTINGS,e.target.elements.remember.checked?safe:{});e.target.elements.password.value='';e.target.elements.smtp_password.value='';$('#accountDialog').close();connectionUI();emptyReader();notice('Connected. Incoming and SMTP logins verified.');try{await loadFolders();}catch(err){notice('Connected, but folders could not be loaded: '+err.message,true);}await refresh();}catch(err){notice(err.message+' Check the server details and whether your provider requires an app password.',true);}finally{button.disabled=false;button.textContent='Connect account →';}};
$('#disconnectBtn').onclick=async()=>{try{await api('disconnect');state.connected=false;state.email='';clearBlobs();resetMailbox();connectionUI();notice('Disconnected. Mail credentials cleared from the service session.');}catch(err){notice(err.message,true);}};
$('#refreshBtn').onclick=refresh;$('#search').oninput=()=>{if(state.connected)renderRows();};$('#prevBtn').onclick=()=>{state.offset=Math.max(0,state.offset-40);emptyReader();refresh();};$('#nextBtn').onclick=()=>{state.offset+=40;emptyReader();refresh();};$('#layoutBtn').onclick=()=>$('.mailbox').classList.toggle('readingHidden');$('[data-inbox]').onclick=()=>needAccount();
function compose(mode){if(!needAccount())return;const f=$('#composeForm');f.reset();state.replyId='';$('#attachmentInfo').textContent='20 MiB maximum';const m=state.current;if(m&&mode==='reply'){f.elements.to.value=m.reply_to;f.elements.subject.value=/^re:/i.test(m.subject)?m.subject:'Re: '+m.subject;f.elements.body.value='\n\nOn '+m.date+', '+m.from+' wrote:\n'+m.body.split('\n').map(s=>'> '+s).join('\n');state.replyId=m.message_id;}if(m&&mode==='forward'){f.elements.subject.value='Fwd: '+m.subject;f.elements.body.value='\n\n---------- Forwarded message ----------\nFrom: '+m.from+'\nDate: '+m.date+'\nSubject: '+m.subject+'\n\n'+m.body;}open('composeDialog');f.elements[mode==='reply'?'body':'to'].focus();}
$('#composeBtn').onclick=()=>compose('new');function closeComposer(){if(state.sending)return;const f=$('#composeForm');if((f.elements.body.value||f.elements.to.value||f.elements.subject.value||$('#attachments').files.length)&&!confirm('Discard this unsent message?'))return;$('#composeDialog').close();}$('#closeCompose').onclick=closeComposer;$('#composeDialog').addEventListener('cancel',e=>{e.preventDefault();closeComposer();});
$('#attachments').onchange=()=>{const files=Array.from($('#attachments').files);$('#attachmentInfo').textContent=files.length?files.map(f=>f.name).join(', ')+` · ${(files.reduce((n,f)=>n+f.size,0)/1048576).toFixed(2)} MiB`:'20 MiB maximum';};
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,data:r.result.split(',')[1]});r.onerror=()=>reject(Error('Could not read '+file.name));r.readAsDataURL(file);});}
$('#composeForm').onsubmit=async e=>{e.preventDefault();if(state.sending)return;const files=Array.from($('#attachments').files);if(files.reduce((n,f)=>n+f.size,0)>20*1048576)return notice('Attachments must total 20 MiB or less.',true);state.sending=true;$('#sendBtn').disabled=true;$('#sendBtn').textContent='Sending…';try{const draft=Object.fromEntries(new FormData(e.target));draft.attachments=await Promise.all(files.map(fileData));draft.in_reply_to=state.replyId;const r=await api('send',draft);$('#composeDialog').close();e.target.reset();notice(r.refused.length?'Sent to accepted recipients. Refused: '+r.refused.join(', '):'Your SMTP server accepted the message.',r.refused.length>0);}catch(err){notice('Send did not complete: '+err.message+' If the connection dropped, check delivery before retrying.',true);}finally{state.sending=false;$('#sendBtn').disabled=false;$('#sendBtn').textContent='Send message ↗';}};
async function showDownloads(){open('downloadsDialog');const rows=$('#downloadRows');rows.replaceChildren(el('p','Loading downloads…','info'));let data;try{data=await fetch('/downloads.json').then(r=>r.json());}catch{data={assets:[]};}if(!(data.assets||[]).length){try{const release=await fetch('https://api.github.com/repos/itswiktoragain/gpt-on-the-move/releases/tags/tmailer-v1.1.0',{credentials:'omit'}).then(r=>r.ok?r.json():null);if(release){const mapping={'windows-x64.msi':'windows','macos-arm64.dmg':'macos-arm64','macos-x64.dmg':'macos-x64','linux.deb':'linux'};data.assets=(release.assets||[]).map(a=>({platform:Object.entries(mapping).find(([suffix])=>a.name.endsWith(suffix))?.[1],url:a.browser_download_url})).filter(a=>a.platform);}}catch{}}rows.replaceChildren();for(const platform of [{id:'windows',icon:'⊞',name:'Windows',detail:'Windows 10 / 11 · x64 · MSI installer'},{id:'macos-arm64',icon:'⌘',name:'macOS · Apple silicon',detail:'macOS 15+ · ARM64 · DMG disk image'},{id:'macos-x64',icon:'⌘',name:'macOS · Intel',detail:'macOS 15+ · x64 · DMG disk image'},{id:'linux',icon:'⌁',name:'Linux',detail:'Linux Mint / Ubuntu / Debian · DEB package'}]){const row=el('div',undefined,'downloadRow');row.append(el('span',platform.icon,'platformIcon'));const info=el('div',undefined,'platformInfo');info.append(el('h3',platform.name),el('p',platform.detail));row.append(info);const asset=(data.assets||[]).find(a=>a.platform===platform.id);if(asset){const a=el('a','Download ↓','downloadLink');a.href=asset.url;a.target='_blank';a.rel='noopener';row.append(a);}else row.append(el('span','Build not available yet','buildPending'));rows.append(row);}}
$('#downloadsBtn').onclick=showDownloads;
window.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus();}});
window.addEventListener('beforeunload',e=>{if(state.sending||($('#composeDialog').open&&$('#composeForm').elements.body.value)){e.preventDefault();e.returnValue='';}});
for(const [key,value] of Object.entries(stored(SETTINGS,{}))){const field=$('#accountForm').elements.namedItem(key);if(field)field.value=value;}
connectionUI();

if(cfg.desktop){api('settings').then(settings=>{for(const [key,value] of Object.entries(settings)){const field=$('#accountForm').elements.namedItem(key);if(field)field.value=value;}}).catch(err=>notice(err.message,true));}
